function twoSum(numbers, target) {
  const seen = new Map()
  for (let index = 0; index < numbers.length; index++) {
    const complement = target - numbers[index]
    if (seen.has(complement)) return [seen.get(complement), index]
    seen.set(numbers[index], index)
  }
  return []
}

