def rotate_right(numbers, steps):
    if not numbers:
        return []
    steps %= len(numbers)
    if steps == 0:
        return numbers.copy()
    return numbers[-steps:] + numbers[:-steps]

function rotateRight(numbers, steps) {
  if (numbers.length === 0) return []
  steps %= numbers.length
  if (steps === 0) return [...numbers]
  return numbers.slice(-steps).concat(numbers.slice(0, -steps))
}

def max_window_sum(numbers, size):
    if size <= 0 or size > len(numbers):
        raise ValueError("invalid window size")
    window_sum = sum(numbers[:size])
    best = window_sum
    for right in range(size, len(numbers)):
        window_sum += numbers[right] - numbers[right - size]
        best = max(best, window_sum)
    return best

function maxWindowSum(numbers, size) {
  if (size <= 0 || size > numbers.length) {
    throw new RangeError('invalid window size')
  }
  let windowSum = numbers.slice(0, size).reduce((sum, n) => sum + n, 0)
  let best = windowSum
  for (let right = size; right < numbers.length; right++) {
    windowSum += numbers[right] - numbers[right - size]
    best = Math.max(best, windowSum)
  }
  return best
}

def deduplicate_sorted(numbers):
    if not numbers:
        return 0
    write = 1
    for read in range(1, len(numbers)):
        if numbers[read] != numbers[write - 1]:
            numbers[write] = numbers[read]
            write += 1
    return write

function deduplicateSorted(numbers) {
  if (numbers.length === 0) return 0
  let write = 1
  for (let read = 1; read < numbers.length; read++) {
    if (numbers[read] !== numbers[write - 1]) {
